# Generated by Django migration to purge non-student StudentMemberProfiles
# and ensure SSOT across all clubs.

from django.db import migrations


def purge_non_student_profiles_and_resync(apps, schema_editor):
    Club = apps.get_model("domain", "Club")
    StudentMemberProfile = apps.get_model("members", "StudentMemberProfile")

    # 1. Purge profiles for users who are Main Admins or Central Admins or Coordinators.
    # Note: Executive Council members (club_executive) represent student leaders.
    non_student_profiles = StudentMemberProfile.objects.filter(
        user__sub_role__in=[
            "club_patron",
            "club_president",
            "club_secretary",
            "subclub_coordinator",
        ]
    ) | StudentMemberProfile.objects.filter(
        user__category__in=["iit_kgp_admin", "general_public"]
    )
    purged_count = non_student_profiles.count()
    if purged_count > 0:
        non_student_profiles.delete()
        print(f"[0008_purge] Purged {purged_count} non-student profiles.")

    # 2. Resync member_count for all Clubs to match true SSOT
    for club in Club.objects.all():
        true_student_count = (
            StudentMemberProfile.objects.filter(club=club)
            .exclude(user__category="iit_kgp_admin")
            .exclude(
                user__sub_role__in=[
                    "club_patron",
                    "club_president",
                    "club_secretary",
                    "subclub_coordinator",
                ]
            )
            .count()
        )
        if club.member_count != true_student_count:
            club.member_count = true_student_count
            club.save(update_fields=["member_count"])


def reverse_noop(apps, schema_editor):
    pass


class Migration(migrations.Migration):

    dependencies = [
        ("members", "0007_schoolstudentroster_status"),
    ]

    operations = [
        migrations.RunPython(
            purge_non_student_profiles_and_resync,
            reverse_code=reverse_noop,
        ),
    ]
